// === Tab: mySketch ===
let particles = [];
let attractor = [];
let target; 
let velLimit = 0.05;
let fixedSpeed = 0.2;

let dt = 0.01;  
let boundaryX, boundaryY, boundaryZ; 
let numParticles = 1000;

let w = 800;
let h = 800;
let box_size = 200;
let fr = 36;
let displayTrace = 1;

let timer;
let nextChange;
let repulse = -1;

function setup() {
  createCanvas(w, h, WEBGL);
  frameRate(fr);

  timer = random(5000,25000);
  nextChange = timer

  // Define the boundaries as half the width, height, and depth
  boundaryX = w / 8;
  boundaryY = h / 8;
  boundaryZ = 200;  

  // Create an array of Particle objects
  for (let i = 0; i < numParticles; i++) {
    particles.push(new Particle(random(-boundaryX, boundaryX), 
                                random(-boundaryY, boundaryY), 
                                random(-boundaryZ, boundaryZ)));
  }  
  // Set the target's initial position
  target = createVector(0.1, 0, 0);  
}

function draw() {
  background(50);
  orbitControl();

  if (millis() > nextChange) {
    repulse = -1 * repulse;
    nextChange = millis() + timer;
    timer = random(5000,25000);
  }

  // Enable 3D rotation
  rotateX(frameCount * 0.01);
  rotateY(frameCount * 0.01);

  // Update the target's position based on attractor equations
  updateAttractor(target);

  // Draw the target point
  push();
    scale(Math.min(w,h)/5);
    stroke(100,150,0);
    strokeWeight(20);
    point(target.x, target.y, target.z); 
  pop();

  //  Toggle to display the attractor's trace
  if(displayTrace == 1) {
    push();
      scale(Math.min(w,h)/5);
      stroke(100,150,0);
      strokeWeight(1);
      noFill();
      beginShape();
        for (let v of attractor) {
          vertex(v.x, v.y, v.z);
        }
      endShape();
    pop();
  }

  // Update and display all Particle objects
  for (let i = 0; i < particles.length; i++) {
    if(repulse == -1) {
      particles[i].moveTowardsTarget(target);
      particles[i].checkEdges();
      particles[i].display(target);
    } else {
      let antiTarget = createVector(random(-boundaryX, boundaryX), 
                                    random(-boundaryY, boundaryY), 
                                    random(-boundaryZ, boundaryZ));
      particles[i].moveTowardsTarget(antiTarget);
      particles[i].checkEdges();
      particles[i].display(antiTarget);
    }

  }
}

// Particle class definition
class Particle {
  constructor(x, y, z) {
    this.pos = createVector(x, y, z);
    this.vel = createVector(0, 0, 0);
    this.acc = createVector(0, 0, 0);
    this.direction = createVector(1, 1, 1);  // Direction modifier (1 or -1)
  }

  // Move the particle towards the target
  moveTowardsTarget(t) {
    let direction = p5.Vector.sub(t, this.pos);
    direction.normalize();
    direction.mult(fixedSpeed); // Set the fixed speed of movement 0.2

    // Update the position directly based on the direction and current movement direction
    this.acc.add(direction);
    this.vel.add(this.acc);
    this.vel.limit(velLimit);
    this.pos.add(this.vel);
    this.pos.add(p5.Vector.mult(direction, this.direction));
    this.acc.mult(0);
  }

    // Check if the particle hits the edges of the box and reverse its direction if needed
  checkEdges() {
    // Check the X boundary
    if (this.pos.x > boundaryX || this.pos.x < -boundaryX) {
      this.direction.x *= -1;  // Reverse X direction
      this.pos.x = constrain(this.pos.x, -boundaryX, boundaryX);  
    }

    // Check the Y boundary
    if (this.pos.y > boundaryY || this.pos.y < -boundaryY) {
      this.direction.y *= -1;  // Reverse Y direction
      this.pos.y = constrain(this.pos.y, -boundaryY, boundaryY);  
    }

    // Check the Z boundary
    if (this.pos.z > boundaryZ || this.pos.z < -boundaryZ) {
      this.direction.z *= -1;  // Reverse Z direction
      this.pos.z = constrain(this.pos.z, -boundaryZ, boundaryZ);  
    }
  }

  // Display the particle
  display(t) {
    let d = p5.Vector.dist(this.pos, t);
    push();
      scale(Math.min(w,h)/5);
      if(d <= 1) {
        stroke("red");
      }
      else {
        stroke("yellow");
      }
      strokeWeight(4);
      point(this.pos.x, this.pos.y, this.pos.z);
    pop();
  }
}

// Function to update target's position using Lorenz or Aizawa attractors
function updateAttractor(target) {
  // Current target position
  let x = target.x;
  let y = target.y;
  let z = target.z;

  //  Lorenz attractor equations
  /*let a = 10.0, b = 28.0, c = 8/3;  // Lorenz parameters
  let dx = a * (-x + y);
  let dy = -x * z + b * x - y;
  let dz = x * y - c * z;*/

  // Aizawa attractor equations
  let a = 0.95, b = 0.7, c = 0.6, d = 3.5, e = 0.25, f = 0.1;  // Aizawa parameters
  var dx = (z - b) * x - d * y;
  var dy = d * x + (z - b) * y;
  var dz = c + a * z - (z ** 3) / 3 - (x ** 2 + y ** 2) * (1 + e * z) + f * z * (x ** 3);

  // Update the target position using Euler's method (simple numerical integration)
  target.x += dx * dt;
  target.y += dy * dt;
  target.z += dz * dt;

  attractor.push(createVector(target.x, target.y, target.z));
}

function keyPressed() {
  displayTrace *= -1;
}

function doubleClicked() {
  displayTrace *= -1;
}

